void*memcpy(void*d,const void*s,unsigned long n){char*a=d;const char*b=s;while(n--)*a++=*b++;return d;} void*memset(void*d,int c,unsigned long n){char*a=d;while(n--)*a++=(char)c;return d;} void*memmove(void*d,const void*s,unsigned long n){char*a=d;const char*b=s;if(a<b)while(n--)*a++=*b++;else{a+=n;b+=n;while(n--)*--a=*--b;}return d;} unsigned long strlen(const char*s){unsigned long n=0;while(s[n])n++;return n;} int strcmp(const char*a,const char*b){while(*a&&*a==*b){a++;b++;}return (unsigned char)*a-(unsigned char)*b;} int strncmp(const char*a,const char*b,unsigned long n){while(n&&*a&&*a==*b){a++;b++;n--;}return n?((unsigned char)*a-(unsigned char)*b):0;} char*strcpy(char*d,const char*s){char*r=d;while((*d++=*s++));return r;} char*strncpy(char*d,const char*s,unsigned long n){char*r=d;while(n&&(*d++=*s++))n--;while(n--)*d++=0;return r;} char*strcat(char*d,const char*s){char*r=d;while(*d)d++;while((*d++=*s++));return r;} char*strchr(const char*s,int c){while(*s&&*s!=(char)c)s++;return *s?(char*)s:0;} int atoi(const char*s){int n=0,sign=1;if(*s=='-'){sign=-1;s++;}while(*s>='0'&&*s<='9')n=n*10+*s++-'0';return n*sign;}
